## AnnotationPolicy and LabelPolicy

```
type AnnotationPolicyList struct {
    unversioned.TypeMeta `json:",inline"`
    unversioned.ListMeta `json:"metadata,omitempty"`

    Items []AnnotationPolicy `json:"items"`
}

type AnnotationPolicy struct {
    unversioned.TypeMeta `json:",inline"`
    ObjectMeta `json:"metadata,omitempty"`

    Spec AnnotationPolicySpec `json:"spec,omitempty"`
}


type AnnotationPolicySpec struct {
    Rules []PolicyRule `json:"rules,omitempty"`
}

type LabelPolicyList struct {
    unversioned.TypeMeta `json:",inline"`
    unversioned.ListMeta `json:"metadata,omitempty"`

    Items []LabelPolicy `json:"items"`
}

type LabelPolicy struct {
    unversioned.TypeMeta `json:",inline"`
    ObjectMeta `json:"metadata,omitempty"`

    Spec LabelPolicySpec `json:"spec,omitempty"`
}

type LabelPolicySpec struct {
    Rules []PolicyRule `json:"rules,omitempty"`
}

type PolicyRule struct {
    // If the PolicyPredicate is met, then all of the actions specified
    // by the remaining fields will applied. 
    PolicyPredicate *PolicyPredicate `json:"policyPredicate,omitempty"` 
    Required map[string]string  `json:"required,omitempty"`     // 
    Forbided map[string]string  `json:"forbided,omitempty"`     // Forbid the sepcified annotation/label
    Permitted map[string]string `json:"permitted,omitempty"`    // Permit ths sepcified annotation/label
    Default map[string]string   `json:"default,omitempty"`      // Add the specified annotations/label to the API Object.
}

type PolicyTargetKind string 

const {
    PolicyTargetNode PolicyTargetKind = "Node"
    PolicyTargetPod  PolicyTargetKind = "Pod"
    ... // Other API Object
}

// TODO: more general and expressive predicate
type PolicyPredicate struct {
    Target   *PolicyTargetKind    // the target of the policy
    NodeSelector *NodeSelector `json:"selector,omitempty"` // if the target is Node, NodeSelector will be used
    PodSelector  *PodSelector  `json:"selector,omitempty"` // if the target is Pod, PodSelector will be used   
